#!/usr/bin/env python3
"""
Generate a Shadow configuration file with many Veilid nodes.
Usage: python generate_shadow_config.py [num_nodes] > shadow-large.yaml
"""

import sys

def generate_config(total_nodes=500):
    # Network topology
    header = '''# Shadow configuration for {total} Veilid nodes with realistic network conditions
# Generated by generate_shadow_config.py
# Run with: shadow shadow-{total}.yaml

general:
  stop_time: 90m
  heartbeat_interval: 60s
  log_level: info
  model_unblocked_syscall_latency: true
  parallelism: 0

network:
  graph:
    type: gml
    inline: |
      graph [
        directed 0
        node [
          id 0
          label "core0"
        ]
        node [
          id 1
          label "core1"
        ]
        node [
          id 2
          label "core2"
        ]
        node [
          id 10
          label "region-eu"
        ]
        node [
          id 11
          label "region-us-east"
        ]
        node [
          id 12
          label "region-us-west"
        ]
        node [
          id 13
          label "region-asia"
        ]
        node [
          id 14
          label "region-oceania"
        ]
        edge [
          source 0
          target 0
          latency "1 ns"
          packet_loss 0.0
        ]
        edge [
          source 1
          target 1
          latency "1 ns"
          packet_loss 0.0
        ]
        edge [
          source 2
          target 2
          latency "1 ns"
          packet_loss 0.0
        ]
        edge [
          source 10
          target 10
          latency "1 ns"
          packet_loss 0.0
        ]
        edge [
          source 11
          target 11
          latency "1 ns"
          packet_loss 0.0
        ]
        edge [
          source 12
          target 12
          latency "1 ns"
          packet_loss 0.0
        ]
        edge [
          source 13
          target 13
          latency "1 ns"
          packet_loss 0.0
        ]
        edge [
          source 14
          target 14
          latency "1 ns"
          packet_loss 0.0
        ]
        edge [
          source 0
          target 1
          latency "5 ms"
          packet_loss 0.001
        ]
        edge [
          source 1
          target 2
          latency "5 ms"
          packet_loss 0.001
        ]
        edge [
          source 0
          target 2
          latency "5 ms"
          packet_loss 0.001
        ]
        edge [
          source 0
          target 10
          latency "10 ms"
          packet_loss 0.002
        ]
        edge [
          source 1
          target 11
          latency "15 ms"
          packet_loss 0.002
        ]
        edge [
          source 1
          target 12
          latency "25 ms"
          packet_loss 0.002
        ]
        edge [
          source 2
          target 13
          latency "40 ms"
          packet_loss 0.003
        ]
        edge [
          source 2
          target 14
          latency "60 ms"
          packet_loss 0.005
        ]
        edge [
          source 10
          target 11
          latency "80 ms"
          packet_loss 0.005
        ]
        edge [
          source 10
          target 13
          latency "120 ms"
          packet_loss 0.008
        ]
        edge [
          source 11
          target 12
          latency "40 ms"
          packet_loss 0.003
        ]
        edge [
          source 12
          target 13
          latency "100 ms"
          packet_loss 0.006
        ]
        edge [
          source 13
          target 14
          latency "80 ms"
          packet_loss 0.005
        ]
      ]

hosts:
'''.format(total=total_nodes)

    print(header)

    # Bootstrap nodes (3) - must use 11.0.0.x to match hardcoded bootstrap address in main.rs
    bootstrap_nodes = [
        ("bootstrap0", "11.0.0.1", 0),
        ("bootstrap1", "11.0.0.2", 1),
        ("bootstrap2", "11.0.0.3", 2),
    ]

    for name, ip, network_id in bootstrap_nodes:
        print(f'''  {name}:
    network_node_id: {network_id}
    ip_addr: {ip}
    bandwidth_down: "1 Gbit"
    bandwidth_up: "1 Gbit"
    processes:
      - path: ../target/release/shadow_node
        start_time: 1s
        expected_final_state: {{exited: 0}}
        environment:
          RUST_LOG: "warn"
          NODE_TYPE: "bootstrap"
          SHADOW_NODE_ID: "{name}"
          LISTEN_ADDR: "{ip}"
          EXPECTED_READERS: "{total_nodes}"
''')

    # Region configuration
    regions = [
        {"name": "eu", "network_id": 10, "base_ip": "11.1", "nodes": int(total_nodes * 0.20)},
        {"name": "use", "network_id": 11, "base_ip": "11.2", "nodes": int(total_nodes * 0.20)},
        {"name": "usw", "network_id": 12, "base_ip": "11.3", "nodes": int(total_nodes * 0.20)},
        {"name": "asia", "network_id": 13, "base_ip": "11.4", "nodes": int(total_nodes * 0.20)},
        {"name": "oce", "network_id": 14, "base_ip": "11.5", "nodes": int(total_nodes * 0.20)},
    ]

    # Node type distribution within each region
    node_types = [
        {"suffix": "fast", "pct": 0.20, "bw_down": "500 Mbit", "bw_up": "100 Mbit", "type": "normal"},
        {"suffix": "med", "pct": 0.50, "bw_down": "100 Mbit", "bw_up": "20 Mbit", "type": "normal"},
        {"suffix": "slow", "pct": 0.20, "bw_down": "25 Mbit", "bw_up": "5 Mbit", "type": "slow"},
        {"suffix": "vslow", "pct": 0.10, "bw_down": "10 Mbit", "bw_up": "2 Mbit", "type": "slow"},
    ]

    start_time = 30  # seconds, after bootstrap

    for region in regions:
        subnet_counter = 1
        ip_counter = 1

        for node_type in node_types:
            count = int(region["nodes"] * node_type["pct"])

            for i in range(1, count + 1):
                name = f"{region['name']}-{node_type['suffix']}-{i:03d}"
                ip = f"{region['base_ip']}.{subnet_counter}.{ip_counter}"

                print(f'''  {name}:
    network_node_id: {region['network_id']}
    ip_addr: {ip}
    bandwidth_down: "{node_type['bw_down']}"
    bandwidth_up: "{node_type['bw_up']}"
    processes:
      - path: ../target/release/shadow_node
        start_time: {start_time}s
        expected_final_state: {{exited: 0}}
        environment:
          RUST_LOG: "warn"
          NODE_TYPE: "{node_type['type']}"
          SHADOW_NODE_ID: "{name}"
          LISTEN_ADDR: "{ip}"
''')

                start_time += 1
                ip_counter += 1
                if ip_counter > 254:
                    ip_counter = 1
                    subnet_counter += 1

if __name__ == "__main__":
    num_nodes = int(sys.argv[1]) if len(sys.argv) > 1 else 500
    generate_config(num_nodes)
